import{_ as r,C as s,o,c as n,a3 as d,E as h,w as i,j as t}from"./chunks/framework.BOoD0M8-.js";const l="/versions/v1.0.0/screens/macros/macro_cv16_lfo.png",_=JSON.parse('{"title":"CV16 LFO Parameter","description":"","frontmatter":{"title":"CV16 LFO Parameter","pageClass":"macro-doc"},"headers":[],"relativePath":"macros/cv16-lfo.md","filePath":"macros/cv16-lfo.md"}'),c={name:"macros/cv16-lfo.md"};function m(p,e,g,u,v,b){const a=s("ManualRelated");return o(),n("div",null,[e[1]||(e[1]=d('<h1 id="cv16-lfo-parameter" tabindex="-1">CV16 LFO Parameter <a class="header-anchor" href="#cv16-lfo-parameter" aria-label="Permalink to &quot;CV16 LFO Parameter&quot;">​</a></h1><p>Sets a setting of a CV16 LFO.</p><p><img src="'+l+'" alt="CV16 LFO Parameter macro" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Change a CV16 LFO&#39;s rate, depth or shape from a knob. The knob changes the LFO&#39;s own setting. <strong>SAVE PROJECT</strong> keeps it, and a morph back to <strong>0%</strong> returns to it.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>LFO INDEX</td><td>LFO 1 – 16</td><td>The CV16 LFO the knob sets.</td></tr><tr><td>CV PARAM.</td><td>LFO setting</td><td>The setting the knob changes. See the table below.</td></tr><tr><td>MINIMUM / MAXIMUM</td><td>The setting&#39;s range</td><td>In the setting&#39;s own units: Hz, %, degrees, volts.</td></tr></tbody></table></div><p>Also <strong>INVERT</strong> and <strong>PICKUP</strong>: see <a href="/versions/v1.0.0/macros/#settings-most-modes-share">Settings most modes share</a>.</p><h2 id="what-the-knob-can-set" tabindex="-1">What the knob can set <a class="header-anchor" href="#what-the-knob-can-set" aria-label="Permalink to &quot;What the knob can set&quot;">​</a></h2><p>Pick it with <strong>CV PARAM.</strong>:</p><table tabindex="0"><thead><tr><th>CV PARAM.</th><th>What it does</th></tr></thead><tbody><tr><td>ENABLED</td><td>Turns the LFO on or off.</td></tr><tr><td>WAVETABLE</td><td>The wave shape.</td></tr><tr><td>FREQUENCY</td><td>How fast it runs.</td></tr><tr><td>FREQ. FROM BPM</td><td>Runs in time with the project tempo.</td></tr><tr><td>PHASE</td><td>Where in the wave it starts.</td></tr><tr><td>DEPTH</td><td>How big the wave is.</td></tr><tr><td>OFFSET</td><td>Shifts the whole wave up or down.</td></tr><tr><td>MINIMUM</td><td>The lowest voltage the LFO reaches.</td></tr><tr><td>MAXIMUM</td><td>The highest voltage the LFO reaches.</td></tr></tbody></table>',11)),h(a,{title:"Related topics"},{default:i(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/v1.0.0/macros/"},"Macros overview")]),t("li",null,[t("a",{href:"/versions/v1.0.0/macros/setting-up-macros"},"Setting up macros")]),t("li",null,[t("a",{href:"/versions/v1.0.0/concepts/modulation"},"Modulation")])],-1)])]),_:1})])}const P=r(c,[["render",m]]);export{_ as __pageData,P as default};
